        checkout_time=#{targetOrder.checkoutTime},


        status = #{targetOrder.status},


        delivery_time = #{targetOrder.deliveryTime},


        estimated_delivery_time = #{targetOrder.estimatedDeliveryTime}


where id = #{id}
  and status = #{expectedStatus}
  and pay_status = #{expectedPayStatus}

  and order_time < #{orderTimeBefore}

